<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Requests\CheckoutRequest; use App\Models\Address; use App\Services\{CartService,OrderService,PayFastService}; use Illuminate\Http\Request; class OrderController extends Controller { public function index(Request $r){return $r->user()->orders()->with('items','vendor','payment')->latest()->paginate();} public function store(CheckoutRequest $r,CartService $carts,OrderService $orders,PayFastService $payfast){$cart=$carts->current($r->user()->id,null);abort_if($cart->items()->count()===0,422,'Cart is empty.');$address=$r->user()->addresses()->findOrFail($r->integer('address_id'));$created=$orders->checkout($cart,$address);return response()->json(['orders'=>$created,'payment'=>$payfast->redirectData($created[0])],201);} public function show(Request $r,string $number){return $r->user()->orders()->with('items.product','vendor','payment')->where('number',$number)->firstOrFail();} }
